         */allowedCredentialIds: [String], 
        /**
         * PEM-encoded P-256 client private key for JWS envelope signing.
         */clientKeyPem: String, 
        /**
         * PEM-encoded P-256 server public key for JWE envelope encryption.
         */serverPublicKeyPem: String) {
        self.serverUrl = serverUrl
        self.clientId = clientId
        self.context = context
        self.authMode = authMode
        self.rpId = rpId
        self.allowedCredentialIds = allowedCredentialIds
        self.clientKeyPem = clientKeyPem
        self.serverPublicKeyPem = serverPublicKeyPem
    }
