public protocol FfiAuthCallback : AnyObject {
    
    func requestPin(pluginId: String) throws  -> Data
    
    func requestWebauthnAssertion(pluginId: String, challenge: Data, rpId: String, allowedCredentials: [Data]) throws  -> Data
    
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
private let IDX_CALLBACK_FREE: Int32 = 0
// Callback return codes
private let UNIFFI_CALLBACK_SUCCESS: Int32 = 0
private let UNIFFI_CALLBACK_ERROR: Int32 = 1
private let UNIFFI_CALLBACK_UNEXPECTED_ERROR: Int32 = 2

// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceFfiAuthCallback {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    static var vtable: UniffiVTableCallbackInterfaceFfiAuthCallback = UniffiVTableCallbackInterfaceFfiAuthCallback(
        requestPin: { (
            uniffiHandle: UInt64,
            pluginId: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> Data in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceFfiAuthCallback.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.requestPin(
                     pluginId: try FfiConverterString.lift(pluginId)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterData.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeFfiWscdError.lower
            )
        },
        requestWebauthnAssertion: { (
            uniffiHandle: UInt64,
            pluginId: RustBuffer,
            challenge: RustBuffer,
            rpId: RustBuffer,
            allowedCredentials: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> Data in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceFfiAuthCallback.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.requestWebauthnAssertion(
                     pluginId: try FfiConverterString.lift(pluginId),
                     challenge: try FfiConverterData.lift(challenge),
                     rpId: try FfiConverterString.lift(rpId),
                     allowedCredentials: try FfiConverterSequenceData.lift(allowedCredentials)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterData.lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeFfiWscdError.lower
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterCallbackInterfaceFfiAuthCallback.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface FfiAuthCallback: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitFfiAuthCallback() {
    uniffi_siros_wscd_manager_fn_init_callback_vtable_ffiauthcallback(&UniffiCallbackInterfaceFfiAuthCallback.vtable)
}

// FfiConverter protocol for callback interfaces
#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterCallbackInterfaceFfiAuthCallback {
    fileprivate static var handleMap = UniffiHandleMap<FfiAuthCallback>()
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
extension FfiConverterCallbackInterfaceFfiAuthCallback : FfiConverter {
    typealias SwiftType = FfiAuthCallback
    typealias FfiType = UInt64

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public static func lift(_ handle: UInt64) throws -> SwiftType {
        try handleMap.get(handle: handle)
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SwiftType {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public static func lower(_ v: SwiftType) -> UInt64 {
        return handleMap.insert(obj: v)
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public static func write(_ v: SwiftType, into buf: inout [UInt8]) {
        writeInt(&buf, lower(v))
    }
}




/**
 * Host-provided raw CTAP2 message transport for the previewSign (WebAuthn
 * "sign extension") plugin.
 *
 * The host SDK owns the channel to the authenticator (BLE/NFC/USB) and
 * all of its transport-specific framing (CTAPHID chunking over USB HID,
 * NFCCTAP_MSG/ISO 7816 APDU wrapping over NFC, ...) - this callback sees
 * only the logical CTAP2 message layer: `command` is a leading
 * command-code byte followed by CBOR params (already built by this
 * crate); the return value is a leading status byte followed by CBOR
 * body (or just the status byte on error), exactly as received from the
 * authenticator. ALL previewSign CBOR request-building and
 * response-parsing lives in [`crate::preview_sign_protocol`] - do not
 * reimplement it in a host SDK. This design is confirmed against real
 * YubiKey 5.8 hardware (2026-08-04).
 */
public protocol FfiCtap2Transport : AnyObject {
    
